//! Auto-generated Joe-Kuo (2008) Sobol direction-number table.
//!
//! Source: Stephen Joe and Frances Y. Kuo, *Constructing Sobol' sequences
//! with better two-dimensional projections*, SIAM J. Sci. Comput. 30 (2008),
//! 2635-2654; data file `new-joe-kuo-6.21201` (BSD-3-Clause licensed),
//! <https://web.maths.unsw.edu.au/~fkuo/sobol/>. Columns are
//! `d s a m_1 .. m_s`: dimension index, primitive-polynomial degree `s`,
//! the polynomial's coefficient bitmask `a`, and the `s` initial direction
//! integers `m_i` (odd, `m_i < 2^i`). Dimension 1 is the special van der
//! Corput / bit-reversal sequence and is handled directly in the generator.
//!
//! Embedded for dimensions `2..=300` (so the generator supports up to 300
//! dimensions including dim 1); a documented, gated bound.

/// One row of the Joe-Kuo table for a single Sobol dimension `d >= 2`.
#[derive(Clone, Copy)]
pub(crate) struct DirRow {
    /// Degree `s` of the primitive polynomial (number of initial `m_i`).
    pub s: u32,
    /// Coefficient bitmask `a` of the primitive polynomial.
    pub a: u32,
    /// The `s` initial direction integers `m_1..m_s` (rest are zero-padded).
    pub m: [u32; MAX_S],
}

/// Maximum polynomial degree `s` across the embedded table.
pub(crate) const MAX_S: usize = 11;

/// Highest Sobol dimension supported by the embedded table (incl. dim 1).
pub const MAX_DIM: usize = 300;

